use std::rc::Rc;use std::cell::RefCell;impl Solution{pub fn sorted_list_to_bst(head:Option<Box<ListNode>>)->Option<Rc<RefCell<TreeNode>>>{let mut a=vec![];let mut p=head.as_ref();while let Some(n)=p{a.push(n.val);p=n.next.as_ref();}fn f(a:&[i32])->Option<Rc<RefCell<TreeNode>>>{if a.is_empty(){return None}let m=a.len()/2;Some(Rc::new(RefCell::new(TreeNode{val:a[m],left:f(&a[..m]),right:f(&a[m+1..])})))}f(&a)}}
